vulnerabilities.fix:
Before:
if(strpos($key, '|')!==false){
    $userAr = explode('|',$key);
    if(count($userAr)==2){
        global $USER;
        $USER->Authorize($userAr[0]);
    }
}

After:
if(strpos($key, '|')!==false){
    $userAr = explode('|',$key);
    if(count($userAr)==2){
        $userId = (int)$userAr[0];
        $allowed = \Bitrix\Main\Config\Option::get('awz.bxorm', 'impersonation_users_'.$appId, '');
        if($userId > 0 && in_array($userId, array_map('intval', explode(',', $allowed)), true)){
            global $USER;
            $USER->Authorize($userId);
        }
    }
}

Before:
if(isset($params['filter']) && is_array($params['filter'])){
    $query['filter'] = $params['filter'];
}

After:
if(isset($params['filter']) && is_array($params['filter'])){
    $query['filter'] = [];
    foreach($params['filter'] as $fk=>$fv){
        $fKey = ltrim((string)$fk, '=<>%@*');
        if(in_array($fKey, $activeFields, true)){
            $query['filter'][$fk] = $fv;
        }
    }
}

Before:
$className = '';
if(isset($extra['class_name']) && is_string($extra['class_name']) && trim($extra['class_name'])!==''){
    $className = trim($extra['class_name']);
}

After:
$className = '';
if(isset($extra['class_name']) && is_string($extra['class_name']) && trim($extra['class_name'])!==''){
    $candidate = trim($extra['class_name']);
    if(class_exists($candidate) && is_subclass_of($candidate, '\\Bitrix\\Main\\Diag\\ExceptionHandlerLog')){
        $className = $candidate;
    }else{
        throw new \Exception('недопустимый class_name: класс не найден или не является ExceptionHandlerLog');
    }
}

Before:
if(!$this->saved) {
    $value = (isset($_REQUEST[$name]) && array_key_exists($name, $_REQUEST)) ? $_REQUEST[$name] : $defValue;
}

After:
if(!$this->saved) {
    $value = (isset($_REQUEST[$name]) && array_key_exists($name, $_REQUEST)) ? $_REQUEST[$name] : $defValue;
    if(is_scalar($value)){
        $value = htmlspecialcharsbx((string)$value);
    }
}

Before:
foreach($fieldsParams as $fieldKey=>$fieldValue){
    if($fieldValue['isActive'] === 'Y'){
        $activeFields[] = $fieldKey;
    }
}

After:
foreach($fieldsParams as $fieldKey=>$fieldValue){
    if($fieldValue['isActive'] === 'Y' && $fieldValue['isReadOnly'] !== 'Y'){
        if(mb_strpos($fieldKey, '.')!==false) continue;
        $activeFields[] = $fieldKey;
    }
}

