Before:
$origin = $this->origin ?: \Bitrix\Main\Context::getCurrent()->getRequest()->getHeader('Origin');
if ($origin){
    $response->addHeader('Access-Control-Allow-Origin', $origin);
}else{
    $response->addHeader('Access-Control-Allow-Origin', "*");
}

After:
$origin = $this->origin ?: \Bitrix\Main\Context::getCurrent()->getRequest()->getHeader('Origin');
$allowed = array_filter(array_map('trim', explode(',', (string)\Bitrix\Main\Config\Option::get('awz.bxorm', 'mcp_cors_origins', ''))));
if($origin && in_array((string)$origin, $allowed, true)){
    $response->addHeader('Access-Control-Allow-Origin', (string)$origin);
}
// без allowlist — CORS-заголовок не устанавливается
